"""Collect additional gate views while retaining uncertain location/date metadata."""
import importlib.util,json,pathlib,urllib.parse,concurrent.futures
R=pathlib.Path(__file__).resolve().parents[1]
s=importlib.util.spec_from_file_location('collector',R/'scripts/collect.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
rows=json.loads((R/'sources.json').read_text());existing={r['id']for r in rows}
new=[dict(id='gate-icoca-2025-page',title='March2025 ICOCA gate close-up metadata; location conflict',url='https://commons.wikimedia.org/wiki/File:ICOCA-Gate_at_Kyoto_Station.jpg',category='photos',format='html',publisher='Mr.ちゅらさん / Wikimedia Commons',source_date='2025-03-23',rights='CC BY-SA 4.0 for photograph; reference use only.',note='Caption says Central Gate, category says West Gate; inspect visible architecture before use for central-gate layout.'),dict(id='gate-icoca-2025',title='March2025 ICOCA gate close-up; location unverified',url='https://upload.wikimedia.org/wikipedia/commons/f/f3/ICOCA-Gate_at_Kyoto_Station.jpg',parent_url='https://commons.wikimedia.org/wiki/File:ICOCA-Gate_at_Kyoto_Station.jpg',category='photos',format='jpg',publisher='Mr.ちゅらさん / Wikimedia Commons',source_date='2025-03-23',rights='CC BY-SA 4.0. Research reference; no game texture use.',note='Caption/category conflict; no station bank count inferred.'),dict(id='gate-korean-01-page',title='Central gate frontal photograph metadata',url='https://commons.wikimedia.org/wiki/File:'+urllib.parse.quote('JR_교토역_개찰구_01.jpg'),category='photos',format='html',publisher='Wikimedia Commons; author/date pending metadata inspection',source_date='Unverified',rights='Inspect file-specific license before redistribution.',note='Listed in Kyoto Station JR Line Central Gate category; location and capture date require image/metadata verification.')]
new=[r for r in new if r['id']not in existing]
with concurrent.futures.ThreadPoolExecutor(max_workers=3)as p:new=list(p.map(m.collect,new))
(R/'sources.json').write_text(json.dumps(rows+new,ensure_ascii=False,indent=2)+'\n')
